<?php
/** Focused tests for provider selection, omissions and native SEO output. */
define( 'ABSPATH', '/' );
class WP_Error { public $code; public function __construct( $code, $message ) { $this->code = $code; } }
function is_wp_error( $value ) { return $value instanceof WP_Error; }
$test_plugins = []; $test_network_plugins = []; $test_multisite = false; $test_meta = []; $test_singular = true; $test_type = 'service_page'; $test_filters = []; $test_block_write = false;
function get_option( $name, $default = false ) { global $test_plugins; return 'active_plugins' === $name ? $test_plugins : $default; }
function is_multisite() { global $test_multisite; return $test_multisite; }
function get_site_option( $name, $default = false ) { global $test_network_plugins; return 'active_sitewide_plugins' === $name ? $test_network_plugins : $default; }
function sanitize_text_field( $value ) { return trim( preg_replace( '/\s+/', ' ', strip_tags( $value ) ) ); }
function metadata_exists( $type, $id, $key ) { global $test_meta; return isset( $test_meta[$id] ) && array_key_exists( $key, $test_meta[$id] ); }
function get_post_meta( $id, $key, $single = false ) { global $test_meta; return $test_meta[$id][$key] ?? ''; }
function update_post_meta( $id, $key, $value ) { global $test_meta, $test_block_write; if ( $test_block_write ) { return false; } $test_meta[$id][$key] = stripslashes( $value ); return true; }
function wp_slash( $value ) { return addslashes( $value ); }
function add_filter( $name, $callback, $priority = 10 ) { global $test_filters; $test_filters[$name] = [ $callback, $priority ]; }
function add_action( $name, $callback, $priority = 10 ) { add_filter( $name, $callback, $priority ); }
function is_singular() { global $test_singular; return $test_singular; }
function get_queried_object_id() { return 12; }
function get_post_type( $id ) { global $test_type; return $test_type; }
function esc_attr( $value ) { return htmlspecialchars( $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8' ); }
function check( $value, $message ) { if ( ! $value ) { throw new Exception( $message ); } }
require __DIR__ . '/../includes/class-nova-bridge-suite-owned-cpt-seo.php';

Nova_Bridge_Suite_Owned_CPT_SEO::bootstrap();
check( isset( $test_filters['wpseo_metadesc'], $test_filters['pre_get_document_title'], $test_filters['wp_head'] ), 'Hooks registered.' );
check( Nova_Bridge_Suite_Owned_CPT_SEO::available(), 'SEO fields are available without an external provider.' );
$values = Nova_Bridge_Suite_Owned_CPT_SEO::plan( 'Example SEO title', 'Example "description"' );
check( count( $values ) === 2 && ! is_wp_error( Nova_Bridge_Suite_Owned_CPT_SEO::apply( 12, $values ) ) && Nova_Bridge_Suite_Owned_CPT_SEO::matches( 12, $values ), 'Built-in canonical fields can be stored and read back.' );
check( Nova_Bridge_Suite_Owned_CPT_SEO::native_title( 'Original' ) === 'Example SEO title', 'No-provider title uses the saved value.' );
ob_start(); Nova_Bridge_Suite_Owned_CPT_SEO::native_description(); $html = ob_get_clean();
check( strpos( $html, 'Example &quot;description&quot;' ) !== false, 'No-provider description is escaped in the head.' );
$before = Nova_Bridge_Suite_Owned_CPT_SEO::read( 12, [ '_nova_posting_seo_title', 'missing' ] );
check( $before['missing'] === [ 'exists' => false, 'value' => '' ] && $before['_nova_posting_seo_title']['exists'], 'Snapshots distinguish absent and empty metadata.' );
$test_plugins = [ 'wp-seopress/seopress.php' ];
$writes = Nova_Bridge_Suite_Owned_CPT_SEO::plan( 'Title', 'Description' );
check( $writes['_seopress_titles_title'] === 'Title' && $writes['_seopress_titles_desc'] === 'Description' && ! isset( $writes['_yoast_wpseo_metadesc'] ), 'Only the active provider receives matching keys.' );
check( Nova_Bridge_Suite_Owned_CPT_SEO::plan( null, ' ' ) === [], 'Missing values never clear existing SEO metadata.' );
check( Nova_Bridge_Suite_Owned_CPT_SEO::native_title( 'Provider title' ) === 'Provider title', 'Native title fallback leaves SEO plugins in control.' );
ob_start(); Nova_Bridge_Suite_Owned_CPT_SEO::native_description(); check( '' === ob_get_clean(), 'No duplicate description tag with an active provider.' );
$test_plugins = [ 'wordpress-seo/wp-seo.php' ]; $writes = Nova_Bridge_Suite_Owned_CPT_SEO::plan( null, 'New description' );
check( ! is_wp_error( Nova_Bridge_Suite_Owned_CPT_SEO::apply( 12, $writes ) ), 'Yoast metadata writes.' );
check( Nova_Bridge_Suite_Owned_CPT_SEO::yoast_description( 'Generated intro' ) === 'New description', 'Service explicit SEO description supersedes its autogenerated intro.' );
$test_meta[12]['_yoast_wpseo_metadesc'] = 'Edited by site owner';
check( Nova_Bridge_Suite_Owned_CPT_SEO::yoast_description( 'Generated intro' ) === 'Edited by site owner', 'Later site-owner SEO edits remain authoritative.' );
$test_type = 'post'; check( Nova_Bridge_Suite_Owned_CPT_SEO::yoast_description( 'Original' ) === 'Original', 'Yoast filter does not affect other post types.' );
$test_plugins = []; $test_multisite = true; $test_network_plugins = [ 'seo-by-rank-math/rank-math.php' => 42 ];
$writes = Nova_Bridge_Suite_Owned_CPT_SEO::plan( 'Network title', null );
check( $writes['rank_math_title'] === 'Network title' && ! isset( $writes['rank_math_description'] ), 'Network provider and absent description are handled.' );
$test_plugins = [ 'all-in-one-seo-pack/all_in_one_seo_pack.php' ]; $test_multisite = false;
ob_start(); Nova_Bridge_Suite_Owned_CPT_SEO::native_description(); check( '' === ob_get_clean(), 'Known unsupported SEO plugins do not get a conflicting fallback tag.' );
$test_block_write = true; check( is_wp_error( Nova_Bridge_Suite_Owned_CPT_SEO::apply( 12, [ '_seopress_titles_desc' => 'unsaved' ] ) ), 'Failed native writes return an error.' );
echo "Owned CPT SEO: 15 checks passed\n";
